// The Unicode case mappings behind `str::to_upper` and `str::to_lower`. The tables are in
// case_tables.cpp, generated by scripts/gen-case-tables.mjs.

#pragma once

#include <cstddef>
#include <cstdint>
#include <string>
#include <string_view>

namespace camel::str {

/// One mapping. `to` is the mapped code point, or, with the high bit set, a sequence: its
/// length is in bits 24..26 and its offset in `caseSequences()` in bits 0..23.
struct CaseEntry {
    uint32_t cp;
    uint32_t to;
};

extern const char *const kUnicodeVersion;
const CaseEntry *upperTable(size_t &count);
const CaseEntry *lowerTable(size_t &count);
const uint32_t *caseSequences();

/// The text with every letter in upper case / lower case by the unconditional Unicode mappings
/// (the text is valid UTF-8; so is the result).
std::string toUpperCase(std::string_view text);
std::string toLowerCase(std::string_view text);

} // namespace camel::str
